from fastapi import FastAPI
from fastapi.testclient import TestClient
from pydantic import BaseModel


class Item(BaseModel):
    name: str
    description: str | None = None
    price: float | None = None


def test_default_response_model_exclude_none_true_excludes_none_fields():
    app = FastAPI(default_response_model_exclude_none=True)

    @app.get("/item", response_model=Item)
    def get_item() -> Item:
        return Item(name="Foo", description=None, price=9.99)

    client = TestClient(app)
    response = client.get("/item")
    assert response.status_code == 200
    payload = response.json()
    assert payload == {"name": "Foo", "price": 9.99}
    assert "description" not in payload


def test_default_response_model_exclude_none_false_includes_none_fields():
    app = FastAPI()

    @app.get("/item", response_model=Item)
    def get_item() -> Item:
        return Item(name="Foo", description=None, price=9.99)

    client = TestClient(app)
    response = client.get("/item")
    assert response.status_code == 200
    payload = response.json()
    assert payload == {"name": "Foo", "description": None, "price": 9.99}
    assert "description" in payload
    assert payload["description"] is None


def test_default_response_model_exclude_none_true_explicit_override_on_route():
    app = FastAPI(default_response_model_exclude_none=True)

    @app.get("/item", response_model=Item)
    def get_item() -> Item:
        # Inherits app-level default: response_model_exclude_none is True,
        # so None fields should be excluded.
        return Item(name="Foo", description=None, price=9.99)

    @app.get("/item-with-none", response_model=Item, response_model_exclude_none=False)
    def get_item_with_none() -> Item:
        # Explicit per-route override: None fields should be included
        # even though the app-level default is True.
        return Item(name="Bar", description=None, price=4.99)

    client = TestClient(app)

    # Inherited True default: None fields are excluded.
    inherited_response = client.get("/item")
    assert inherited_response.status_code == 200
    inherited_payload = inherited_response.json()
    assert inherited_payload == {"name": "Foo", "price": 9.99}
    assert "description" not in inherited_payload

    # Explicit False override: None fields are included.
    explicit_response = client.get("/item-with-none")
    assert explicit_response.status_code == 200
    explicit_payload = explicit_response.json()
    assert explicit_payload == {
        "name": "Bar",
        "description": None,
        "price": 4.99,
    }
    assert "description" in explicit_payload
    assert explicit_payload["description"] is None


def test_default_response_model_exclude_none_attribute_default_is_false():
    # The app-level default should default to False when not provided.
    app = FastAPI()
    assert app.default_response_model_exclude_none is False


def test_default_response_model_exclude_none_attribute_when_set_true():
    app = FastAPI(default_response_model_exclude_none=True)
    assert app.default_response_model_exclude_none is True

